				cwd = pane.CWD
				if pane.Agent != "" {
					name = pane.Agent
				}
				break
			}
		}
		for _, agent := range snapshot.Agents {
			if agent.PaneID == paneID && agent.Agent != "" {
				name = agent.Agent
				break
			}
		}
		if cwd == "" {
			cwd = string(os.PathSeparator)
		}
		pid := os.Getpid()
		result, err := json.Marshal(map[string]any{"process_info": map[string]any{"pane_id": paneID, "shell_pid": pid, "foreground_process_group_id": pid, "foreground_processes": []map[string]any{{"pid": pid, "name": name, "cwd": cwd}}}})
		return result, err
	}
	return json.RawMessage(`{}`), nil
}

func (f *Fake) Status(context.Context) (Status, error) {
	f.mu.Lock()
	defer f.mu.Unlock()
	return f.Server, nil
}

func (f *Fake) CheckProtocol(context.Context) error {
	f.mu.Lock()
	defer f.mu.Unlock()
	if !f.Server.Running {
		return &Error{Code: "herdr_unavailable", Message: "Herdr server is not running"}
	}
	if f.Server.Protocol < MinimumProtocol || !f.Server.Compatible {
		return &Error{Code: "herdr_protocol_incompatible", Message: "Herdr protocol is incompatible"}
	}
	return nil
}

