		t.Fatal(err)
	}
	if err := db.Close(); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(filepath.Join(task.WorktreePath, ".posse-e2e-agent-exit"), nil, 0o600); err != nil {
		t.Fatal(err)
	}
